{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@yuting4281/opencode-usage-plugin",
  "version": "0.3.0",
  "type": "module",
  "description": "OpenCode TUI plugin — shows AI provider usage (GitHub Copilot, Kiro, Grok, etc.) with collapsible panels and /usage screen.",
  "exports": {
    ".": "./tui.tsx",
    "./tui": "./tui.tsx"
  },
  "files": [
    "tui.tsx",
    "scripts/",
    "README.md",
    "resources/",
    "LICENSE"
  ],
  "bin": {
    "opencode-auth-usage": "./scripts/opencode-auth-usage.mjs"
  },
  "engines": {
    "opencode": ">=2.0.28",
    "node": ">=22"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "usage",
    "copilot",
    "kiro",
    "grok",
    "xai",
    "tui"
  ],
  "license": "MIT",
  "author": "Toby",
  "repository": {
    "type": "git",
    "url": "https://github.com/fdsf53451001/opencode-usage-plugin"
  },
  "homepage": "https://github.com/fdsf53451001/opencode-usage-plugin#readme",
  "bugs": {
    "url": "https://github.com/fdsf53451001/opencode-usage-plugin/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "check": "tsc --noEmit",
    "test": "node --test tests/*.test.mjs",
    "prepublishOnly": "npm run check && npm test"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.28"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/theme": "^2.0.28",
    "@opentui/core": "^0.5.17",
    "@opentui/solid": "^0.5.17",
    "solid-js": "^1.9.10",
    "@types/node": "^22.13.9",
    "typescript": "^5.8.2"
  }
}
